fn check_is_null(is_null: bool, payload_value: &Value) -> bool {
    match payload_value {
        Value::Null => is_null,
        Value::Bool(_) => !is_null,
        Value::Number(_) => !is_null,
        Value::String(_) => !is_null,
        Value::Array(array) => array.iter().any(|x| x.is_null()) == is_null,
        Value::Object(_) => !is_null,  // Bug: treats empty objects as not-null
    }
}

fn check_empty(&self) -> bool {
    let FieldCondition {
        r#match: _,
        range: _,
        geo_radius: _,
        geo_bounding_box: _,
        geo_polygon: _,
        values_count: _,
        key: _,
        is_empty,
        is_null,
    } = self;
    if let Some(is_empty) = is_empty {
        return *is_empty;
    }
    if let Some(is_null) = is_null {
        return !*is_null;  // Bug: inverted logic for missing keys
    }
    false
}
